args.command:
$jobId = "f3ee1495b2e4"
$start = Get-Date
Write-Output "START: $($start.ToString('o')) job=$jobId"
$deadline = (Get-Date).AddSeconds(400)
$last = $null
while ((Get-Date) -lt $deadline) {
  try {
    $r = Invoke-RestMethod -Uri "http://localhost:8000/api/v1/jobs/$jobId" -Method Get -TimeoutSec 15
    $now = Get-Date
    $elapsed = [int](($now - $start).TotalSeconds)
    $status = $r.status; $stage = $r.stage
    Write-Output "[$elapsed`s] status=$status stage=$stage"
    $last = ($r | ConvertTo-Json -Depth 10 -Compress)
    if ($status -eq "ready" -or $status -eq "failed") {
      Write-Output "FINAL_JSON: $last"
      break
    }
  } catch {
    Write-Output "POLL_ERR: $($_.Exception.Message)"
  }
  Start-Sleep -Seconds 10
}
$finish = Get-Date
$total = [int](($finish - $start).TotalSeconds)
Write-Output "FINISH: $($finish.ToString('o')) total_seconds=$total"
if ($last) { Write-Output "LAST: $last" }

New-Item -ItemType Directory -Force -Path storage/videos | Out-Null
$url = "http://localhost:8000/v/f3ee1495b2e4.mp4"
$dest = "storage/videos/agent1-chai.mp4"
Write-Output "Downloading $url -> $dest"
Invoke-WebRequest -Uri $url -OutFile $dest -TimeoutSec 120
$info = Get-Item $dest
Write-Output "BYTES: $($info.Length)"
if ($info.Length -gt 102400) { Write-Output "SIZE_OK: larger than 100KB" } else { Write-Output "SIZE_FAIL"; exit 1 }
# ffprobe if available
try {
  $probe = & ffprobe -v error -show_entries format=duration -show_entries stream=codec_type,codec_name -of json $dest 2>&1
  Write-Output "FFPROBE_JSON: $probe"
} catch { Write-Output "FFPROBE_MISSING: $($_.Exception.Message)" }
# fallback: try ffmpeg -i
try { & ffmpeg -version 2>&1 | Select-Object -First 2 } catch { Write-Output "FFMPEG_CHECK_FAIL" }
